const scriviCopiaAssociazione = `-- name: ScriviCopiaAssociazione :many
UPDATE documento_proposta p
   SET componente_id = c.componente_id,
       codice = c.codice,
       thread_id = c.thread_id,
       dettagli = CASE WHEN p.componente_id IS NULL
                       THEN COALESCE(p.dettagli, '{}'::jsonb) || jsonb_build_object('codice_letto', p.codice)
                       ELSE p.dettagli END
  FROM componente c
 WHERE p.allegato_id = $1 AND p.stato = 'aperta'
   AND (p.thread_id IS NULL OR p.thread_id = c.thread_id)
   AND c.componente_id = $2 AND c.thread_id = $3
RETURNING p.proposta_id
`

type ScriviCopiaAssociazioneParams struct {
	AllegatoID   uuid.UUID `json:"allegato_id"`
	ComponenteID uuid.UUID `json:"componente_id"`
	ThreadID     uuid.UUID `json:"thread_id"`
}

// La copia derivata di compatibilita' (direttiva 35 §3): la proposta aperta dell'allegato prende il componente della AR e
// il suo codice (la FK a tre campi lo vuole uguale). Prima della copia la lettura del codice si conserva in
// dettagli.codice_letto (DIR35-DP, INC-G4): solo quando la proposta non aveva ancora una copia, e anche quando la lettura
// e' vuota (JSON null), cosi' lo scollegamento la rimette e impronta-ingressi-2 legge sempre la stessa lettura. La
// proposta senza RFQ prende la RFQ della AR (ck_proposta_componente_thread).
func (q *Queries) ScriviCopiaAssociazione(ctx context.Context, arg ScriviCopiaAssociazioneParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, scriviCopiaAssociazione, arg.AllegatoID, arg.ComponenteID, arg.ThreadID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var proposta_id uuid.UUID
		if err := rows.Scan(&proposta_id); err != nil {
			return nil, err
		}
		items = append(items, proposta_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const togliCopiaAssociazione = `-- name: TogliCopiaAssociazione :many
UPDATE documento_proposta p
   SET componente_id = NULL,
       codice = CASE WHEN p.dettagli ? 'codice_letto' THEN p.dettagli ->> 'codice_letto' ELSE p.codice END,
       dettagli = p.dettagli - 'codice_letto'
 WHERE p.allegato_id = $1 AND p.stato = 'aperta' AND p.componente_id = $2
RETURNING p.proposta_id
`

type TogliCopiaAssociazioneParams struct {
	AllegatoID   uuid.UUID     `json:"allegato_id"`
	ComponenteID uuid.NullUUID `json:"componente_id"`
}

// La copia tolta dalla proposta aperta dell'allegato, se dice ancora quel componente: il codice torna la lettura
// conservata in dettagli.codice_letto (se c'e'), e la chiave esce dai dettagli.
func (q *Queries) TogliCopiaAssociazione(ctx context.Context, arg TogliCopiaAssociazioneParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, togliCopiaAssociazione, arg.AllegatoID, arg.ComponenteID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var proposta_id uuid.UUID
		if err := rows.Scan(&proposta_id); err != nil {
			return nil, err
		}
		items = append(items, proposta_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
